UPDATE flt10_tr
   SET flt10_unfill_yn = CAST(#{unfillYn} AS varchar)
 WHERE flt10_tr_id      = #{trId}
   AND flt10_company_id = #{companyId}
   AND flt10_person_id  = #{personId}

mapper.select:
SELECT FROM ( WHERE 1=1 AND flt10_company_id = #{companyId} AND flt10_person_id = #{personId}
AND flt10_account_id = #{accountId}
AND flt03_family_relate_cd = '1'
AND flt10_tr_type LIKE #{trType} AND flt10_tr_type IN ( SELECT sys09_code FROM sys13_code_group INNER JOIN sys09_code ON sys09_code_id = sys13_code_id WHERE sys13_kind_group_cd IN ('FloorTrCode0001','FloorTrCode0004') ) AND ( ( flt10_tr_date IS NULL AND 'Y' = CASE WHEN COALESCE(flt10_status_cd,'00') IN ('20','25') THEN 'Y' ELSE 'N' END ) OR /*(2026.05.15 CYY - 승인건만 조회)*/ ( flt10_tr_date IS NOT NULL ) ) AND ( ( #{preTrYn} = 'true' AND ( ( flt10_tr_date IS NOT NULL AND flt10_tr_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date) ) OR ( flt10_tr_date IS NULL AND flt10_reg_date <= CAST(#{closeDate} AS date) AND flt10_expect_tr_date >= CAST(#{startDate} AS date) ) ) ) OR ( #{preTrYn} = 'false' AND flt10_tr_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date) ) ) AND COALESCE(flt10_unfill_yn, 'false') != 'true' /*미체결 사전신고거래 제외*/ ) a WHERE 1=1
AND CONCAT(flt10_tr_item_type_nm, flt10_tr_item_nm, flt10_tr_item_cd, flt10_item_nm) ILIKE #{searchText}
ORDER BY COALESCE(flt10_reg_date, flt10_tr_date) desc, flt10_account_no, flt10_item_nm collate "ko_KR.utf8" asc, flt10_tr_type

SELECT TO_CHAR(MAX(flt13_book_date), 'YYYY-MM-DD')
  FROM flt13_book_init
 WHERE flt13_company_id = #{companyId}
   AND flt13_person_id  = #{personId}

