UPDATE flt10_tr
   SET flt10_account_id   = #{req.accountId},
       flt10_tr_type      = #{req.trType},
       flt10_tr_date      = CAST(#{req.trDate} AS date),
       flt10_tr_item_type = #{req.trItemType},
       flt10_tr_item_nm   = #{req.trItemName},
       flt10_tr_item_cd   = #{req.trItemCode},
       flt10_tr_qty       = #{req.trQty},
       flt10_tr_amt       = #{req.trAmt},
       flt10_tr_note      = #{req.trNote}
 WHERE flt10_tr_id      = #{req.trId}
   AND flt10_company_id = #{companyId}
   AND flt10_person_id  = #{personId}

UPDATE flt10_tr
   SET flt10_appr_id = null
 WHERE flt10_appr_id    = #{apprId}
   AND flt10_company_id = #{companyId}
   AND flt10_person_id  = #{personId}

