INSERT INTO apr99_appr_del
SELECT f_create_seq()
     , apr01_appr_id, apr01_title, apr01_reg_date, apr01_status_cd, apr01_content, apr01_note, apr01_reg_emp_id, apr01_effect_date
     , apr01_class_tree_id, apr01_stamp_id, apr01_receive_nm, apr01_reference_nm, apr01_stamp_seq, apr01_inout_cd
     , f_sysdate(), #{personId}
     , apr01_company_id, apr01_form_type, apr01_dcr_id_word, apr01_sign_company, apr01_sign_ceo, apr01_stamp_position, apr01_link_cd
  FROM apr01_appr
 WHERE apr01_appr_id    = #{apprId}
   AND apr01_company_id = #{companyId}
   AND apr01_reg_emp_id = #{personId}

