 WHERE apr01_appr_id    = #{apprId}
   AND apr01_company_id = #{companyId}
   AND apr01_reg_emp_id = #{personId}

mapper.select:
SELECT flt03_account_id
  FROM flt03_account
       LEFT OUTER JOIN sys15_corp ON sys15_corp_id = flt03_corp_id AND sys15_company_id = flt03_company_id
 WHERE flt03_company_id = #{companyId}
   AND flt03_person_id  = #{personId}
   AND TO_DECRYPTS(flt03_account_no) LIKE #{accountNo}
 ORDER BY flt03_setup_date, sys15_corp_nm collate "ko_KR.utf8" asc, TO_DECRYPTS(flt03_account_no)

SELECT com50_item_nm
  FROM com50_item
 WHERE com50_item_cd = #{itemCode}
